UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","headingLine1":"Founded in Conviction.","headingAccent":"Grown in Purpose.","paragraphs":["Bodhisattva Museum & Art Gallery was founded in 2000 by Siddhartha Man Shakya, a collector, scholar, and educator who believed Nepal''s Buddhist artistic heritage was being underserved by existing cultural institutions. What began with 200 carefully selected objects in a converted haveli in Civil Lines, Lalitpur, has grown into one of Asia''s foremost institutions of its kind.","Over nearly three decades, the museum has built deep partnerships with institutions across South and Southeast Asia, Japan, the UK, and the United States — establishing scholarly exchange programs, jointly curated exhibitions, and shared digitization initiatives that have set new standards for the field.","In 2012, the Bodhisattva Foundation was established as the museum''s social responsibility arm, extending its mandate from collecting to community-building."],"image":{"url":"https://images.unsplash.com/photo-1765470129726-3689336ff549?w=800&h=450&fit=crop&auto=format&q=80","alt":"Grand museum interior"},"imageAspect":"16:9","quote":{"text":"The Bodhisattva is the figure who postpones their own liberation to remain in the world, to serve. Our museum aspires to that same ethic.","attribution":"Siddhartha Man Shakya · Co-Founder"}}' WHERE p.`slug` = 'about' AND ps.`sort_order` = 1;
