UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"Overview","headingLine1":"Three Floors. Three Millennia.","headingAccent":"One Continuous Story.","paragraphs":["Spread across 28,000 sq. ft. in the heart of Lalitpur, Bodhisattva Museum houses the subcontinent''s most comprehensive permanent collection of Buddhist art. Our galleries trace iconographic development from the pre-Asokan period through the Pala, Gupta, and Vijayanagara empires to the contemporary moment.","The museum is organized around a principle of living dialogue: ancient works are displayed in conversation with contemporary artistic responses, encouraging visitors to see tradition not as a fixed archive but as a generative force."],"facts":[{"label":"Established","value":"2000"},{"label":"Total Area","value":"28,000 sq.ft."},{"label":"Artifacts","value":"12,400+"},{"label":"Annual Visitors","value":"2.1 Million"},{"label":"Active Galleries","value":"18 Rooms"},{"label":"Languages","value":"8 Supported"}]}' WHERE p.`slug` = 'museum' AND ps.`sort_order` = 1;
